"OLAYLAR_GEZGINLER:1813-05-11:0":{"b": ["Emu Plains – Mount York – Mount Blaxland (Blaxland-Lawson-Wentworth 1813)", "6357631e"], "d": ["Rute: Emu Plains → Mount York → Mount Blaxland. Seluruh perjalanan ditampilkan di peta sebagai garis perjalanan.", "9ab9845b"]},
"OLAYLAR_GEZGINLER:1814-01-01:0":{"b": ["Emu Plains – Mount York – Bathurst (Jalan Cox, Great Western Road)", "f38e23c1"], "d": ["Rute: Emu Plains → Mount York → Bathurst. Seluruh perjalanan ditampilkan di peta sebagai garis perjalanan.", "e2cb503f"]},
