"OLAYLAR_GEZGINLER:1817-04-26:0":{"b": ["Bowdich 1817: Cape Coast – jalur Annamaboe – Mansu – Assin – Fomena – Kumasi (jalur Asante)", "f72cd221"], "d": ["Rute: Cape Coast → Kumasi. Seluruh perjalanan ditampilkan di peta sebagai garis perjalanan.", "842baccb"]},
"OLAYLAR_GEZGINLER:1818-01-01:0":{"b": ["Padang – Padang Panjang – Bukittinggi – Batusangkar/Pagaruyung (jalur Minangkabau)", "0c143d03"], "d": ["Rute: Padang → Solok (Solo Solaya) → Danau Singkarak (Sindangbaher) → Simawang → Suruasa → Pagaruyung. Seluruh perjalanan ditampilkan di peta sebagai garis perjalanan.", "656a61c1"]},
